"use client";

import React, { useEffect, useState, useRef, useMemo } from "react";
import { QRCodeSVG } from "qrcode.react";
import {
  Plus, Trash2, User, Users, QrCode, Home, Zap, Droplets, Wifi, Flame, Tv, ShoppingBag,
  Music, Car, Utensils, HeartPulse, Gamepad2, Smartphone, Sparkles, Wallet, X, Check, Settings2, Globe,
} from "lucide-react";

type Cat = { id: string; name: string; icon: typeof Home; color: string };
const CATS: Cat[] = [
  { id: "hogar", name: "Hogar y servicios", icon: Home, color: "var(--chart-1)" },
  { id: "subs", name: "Suscripciones", icon: Tv, color: "var(--chart-4)" },
  { id: "comida", name: "Comida", icon: Utensils, color: "var(--chart-2)" },
  { id: "transporte", name: "Transporte", icon: Car, color: "var(--chart-5)" },
  { id: "salud", name: "Salud", icon: HeartPulse, color: "var(--chart-3)" },
  { id: "ocio", name: "Ocio", icon: Gamepad2, color: "var(--accent)" },
  { id: "compras", name: "Compras", icon: ShoppingBag, color: "var(--primary)" },
];
const catById = (id: string) => (CATS.find((c) => c.id === id) ?? CATS[0])!;

const ICONS: Record<string, typeof Home> = {
  zap: Zap, droplets: Droplets, wifi: Wifi, flame: Flame, phone: Smartphone,
  tv: Tv, cart: ShoppingBag, music: Music, sparkles: Sparkles, home: Home,
  food: Utensils, car: Car, health: HeartPulse, game: Gamepad2, wallet: Wallet,
};
const ICON_KEYS = Object.keys(ICONS);

type Preset = { id: string; name: string; cat: string; icon: string };
type PresetDraft = { id?: string; name: string; cat: string; icon: string };
type Currency = "USD" | "EUR" | "ARS" | "COP";

const DEFAULT_PRESETS: Preset[] = [
  { id: "luz", name: "Luz", cat: "hogar", icon: "zap" },
  { id: "agua", name: "Agua", cat: "hogar", icon: "droplets" },
  { id: "internet", name: "Internet", cat: "hogar", icon: "wifi" },
  { id: "gas", name: "Gas", cat: "hogar", icon: "flame" },
  { id: "telefono", name: "Teléfono", cat: "hogar", icon: "phone" },
  { id: "netflix", name: "Netflix", cat: "subs", icon: "tv" },
  { id: "amazon", name: "Amazon Prime", cat: "subs", icon: "cart" },
  { id: "spotify", name: "Spotify", cat: "subs", icon: "music" },
  { id: "disney", name: "Disney+", cat: "subs", icon: "sparkles" },
  { id: "hbo", name: "HBO Max", cat: "subs", icon: "tv" },
];

type Expense = { id: string; name: string; amount: number; cat: string; date: string; who: "yo" | "pareja"; shared: boolean };

const formatMoney = (n: number, currency: Currency) => {
  const locales: Record<Currency, string> = {
    USD: "en-US",
    EUR: "es-ES",
    ARS: "es-AR",
    COP: "es-CO",
  };
  return n.toLocaleString(locales[currency], { style: "currency", currency });
};

function useCountUp(target: number) {
  const [val, setVal] = useState(target);
  const prev = useRef(target);
  useEffect(() => {
    const from = prev.current;
    prev.current = target;
    const start = performance.now();
    const dur = 650;
    let raf = 0;
    const tick = (t: number) => {
      const p = Math.min(1, (t - start) / dur);
      setVal(from + (target - from) * (1 - Math.pow(1 - p, 3)));
      if (p < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [target]);
  return val;
}

export default function Dashboard() {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [mode, setMode] = useState<"individual" | "pareja">("individual");
  const [currency, setCurrency] = useState<Currency>("USD");
  const [code, setCode] = useState("");
  const [partner, setPartner] = useState<string | null>(null);
  const [qrOpen, setQrOpen] = useState(false);
  const [addOpen, setAddOpen] = useState(false);
  const [form, setForm] = useState({ name: "", amount: "", cat: "comida", shared: false, who: "yo" as "yo" | "pareja" });
  const [filter, setFilter] = useState<string | null>(null);
  const [joinCode, setJoinCode] = useState("");
  const [preset, setPreset] = useState<Preset | null>(null);
  const [presetAmount, setPresetAmount] = useState("");
  const [presetWho, setPresetWho] = useState<"yo" | "pareja">("yo");
  const [presets, setPresets] = useState<Preset[]>(DEFAULT_PRESETS);
  const [manage, setManage] = useState(false);
  const [presetEdit, setPresetEdit] = useState<PresetDraft | null>(null);
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
    const lang = navigator.language || "";
    if (tz.includes("Argentina") || lang.includes("AR")) {
      setCurrency("ARS");
    } else if (tz.includes("Bogota") || tz.includes("Colombia") || lang.includes("CO")) {
      setCurrency("COP");
    } else if (lang.startsWith("es") && !lang.includes("MX") && !lang.includes("AR") && !lang.includes("CO")) {
      setCurrency("EUR");
    }

    const savedCurrency = localStorage.getItem("gastos-currency") as Currency;
    if (savedCurrency) setCurrency(savedCurrency);

    const raw = localStorage.getItem("gastos");
    if (raw) setExpenses(JSON.parse(raw));
    let c = localStorage.getItem("gastos-code");
    if (!c) { c = Math.random().toString(36).slice(2, 8).toUpperCase(); localStorage.setItem("gastos-code", c); }
    setCode(c);
    setPartner(localStorage.getItem("gastos-partner"));
    const join = new URLSearchParams(window.location.search).get("unir");
    if (join && join !== c) { localStorage.setItem("gastos-partner", join); setPartner(join); setMode("pareja"); }
    const rawPresets = localStorage.getItem("gastos-presets");
    if (rawPresets) {
      try {
        const parsed = JSON.parse(rawPresets) as Preset[];
        if (Array.isArray(parsed)) setPresets(parsed.filter((p) => p && p.id && p.name && ICONS[p.icon]));
      } catch {}
    }
    setReady(true);
  }, []);

  useEffect(() => { if (ready) localStorage.setItem("gastos", JSON.stringify(expenses)); }, [expenses, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-presets", JSON.stringify(presets)); }, [presets, ready]);
  useEffect(() => { if (ready) localStorage.setItem("gastos-currency", currency); }, [currency, ready]);

  const add = (e: Omit<Expense, "id" | "date">) =>
    setExpenses((p) => [{ ...e, id: crypto.randomUUID(), date: new Date().toISOString() }, ...p]);

  const visible = useMemo(
    () => expenses.filter((e) => (mode === "individual" ? !e.shared : e.shared)).filter((e) => !filter || e.cat === filter),
    [expenses, mode, filter],
  );
  const scoped = expenses.filter((e) => (mode === "individual" ? !e.shared : e.shared));
  const total = scoped.reduce((s, e) => s + e.amount, 0);
  const byCat = CATS.map((c) => ({ ...c, total: scoped.filter((e) => e.cat === c.id).reduce((s, e) => s + e.amount, 0) }))
    .filter((c) => c.total > 0).sort((a, b) => b.total - a.total);
  const mine = scoped.filter((e) => e.who === "yo").reduce((s, e) => s + e.amount, 0);
  const theirs = total - mine;
  const balance = (mine - theirs) / 2;
  const animatedTotal = useCountUp(total);

  const link = typeof window !== "undefined" ? `${window.location.origin}/?unir=${code}` : "";

  const submit = () => {
    const amount = parseFloat(form.amount);
    if (!form.name || !amount) return;
    add({ name: form.name, amount, cat: form.cat, shared: mode === "pareja", who: form.who });
    setForm({ ...form, name: "", amount: "" });
    setAddOpen(false);
  };

  const submitPreset = () => {
    const amount = parseFloat(presetAmount);
    if (!preset || !amount || amount <= 0) return;
    add({ name: preset.name, amount, cat: preset.cat, shared: mode === "pareja", who: presetWho });
    setPreset(null);
    setPresetAmount("");
  };

  const removePreset = (id: string) => setPresets((p) => p.filter((x) => x.id !== id));

  const savePreset = () => {
    const name = presetEdit?.name.trim();
    if (!presetEdit || !name) return;
    const next = { ...presetEdit, name };
    setPresets((p) =>
      presetEdit.id ? p.map((x) => (x.id === presetEdit.id ? { ...next, id: presetEdit.id } : x)) : [...p, { ...next, id: crypto.randomUUID() }],
    );
    setPresetEdit(null);
  };

  return (
    <div className="min-h-screen pb-24">
      <div className="mx-auto max-w-5xl px-4 pt-6 sm:px-6">
        <header className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between animate-fade-up">
          <div className="flex items-center gap-3">
            <div className="grid h-12 w-12 place-items-center rounded-2xl border border-primary/40 bg-primary/15 shadow-[0_0_24px_-6px_var(--primary)]">
              <Wallet className="h-6 w-6 text-primary" />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight">Mis Gastos</h1>
              <p className="text-xs font-semibold uppercase tracking-[0.2em] text-muted-foreground">
                {new Date().toLocaleDateString("es", { month: "long", year: "numeric" })}
              </p>
            </div>
          </div>

          <div className="flex flex-wrap items-center gap-2">
            {/* Selector de moneda */}
            <div className="flex items-center gap-1.5 rounded-2xl border border-border bg-secondary/60 px-3 py-2 backdrop-blur-md">
              <Globe className="h-4 w-4 text-muted-foreground" />
              <select
                value={currency}
                onChange={(e) => setCurrency(e.target.value as Currency)}
                className="bg-transparent text-sm font-semibold outline-none cursor-pointer"
              >
                <option value="USD" className="bg-popover text-popover-foreground">USD ($)</option>
                <option value="EUR" className="bg-popover text-popover-foreground">EUR (€)</option>
                <option value="ARS" className="bg-popover text-popover-foreground">ARS ($)</option>
                <option value="COP" className="bg-popover text-popover-foreground">COP ($)</option>
              </select>
            </div>

            {/* Selector de Modo */}
            <div className="flex rounded-2xl border border-border bg-secondary/60 p-1.5 backdrop-blur-md">
              {(["individual", "pareja"] as const).map((m) => (
                <button key={m} onClick={() => { setMode(m); setFilter(null); }}
                  className={`flex items-center gap-1.5 rounded-xl px-4 py-2 text-sm font-semibold transition-all duration-300 ${mode === m ? "bg-primary text-primary-foreground shadow-lg shadow-primary/30" : "text-muted-foreground hover:text-foreground"}`}>
                  {m === "individual" ? <User className="h-4 w-4" /> : <Users className="h-4 w-4" />}
                  <span className="hidden sm:inline">{m === "individual" ? "Individual" : "En pareja"}</span>
                </button>
              ))}
            </div>
          </div>
        </header>

        {/* Total */}
        <section className="hero-glow relative mt-6 overflow-hidden rounded-3xl border border-primary/30 p-6 text-primary-foreground shadow-2xl sm:p-8">
          <div className="animate-blob absolute -right-16 -top-20 h-64 w-64 rounded-full bg-white/15 blur-3xl" />
          <div className="animate-blob-alt absolute -bottom-24 -left-10 h-56 w-56 rounded-full bg-white/10 blur-3xl" />
          <div className="relative z-10">
            <p className="text-sm font-medium tracking-wide opacity-90">
              {mode === "individual" ? "Gastaste este mes" : "Gastos compartidos"}
            </p>
            <p className="mt-1 text-5xl font-bold tracking-tight sm:text-6xl">{formatMoney(animatedTotal, currency)}</p>
            {mode === "pareja" && (
              <div className="mt-5 flex flex-wrap items-center gap-3">
                {partner ? (
                  <>
                    <span className="rounded-full bg-primary-foreground/15 px-3 py-1 text-sm backdrop-blur-sm">Emparejado con {partner}</span>
                    <span className="text-sm opacity-90">
                      Tú: {formatMoney(mine, currency)} · Pareja: {formatMoney(theirs, currency)} ·{" "}
                      {balance === 0 ? "Están a mano" : balance > 0 ? `Tu pareja te debe ${formatMoney(balance, currency)}` : `Debes ${formatMoney(-balance, currency)}`}
                    </span>
                  </>
                ) : (
                  <button onClick={() => setQrOpen(true)} className="flex items-center gap-2 rounded-full bg-primary-foreground/15 px-4 py-2 text-sm font-medium backdrop-blur-sm transition hover:scale-105 hover:bg-primary-foreground/25">
                    <QrCode className="h-4 w-4" /> Emparejar con QR
                  </button>
                )}
                {partner && <button onClick={() => setQrOpen(true)} className="text-sm underline opacity-80 transition hover:opacity-100">Ver QR</button>}
              </div>
            )}
          </div>
        </section>

        {/* Presets */}
        <section className="mt-8">
          <div className="mb-3 flex flex-wrap items-baseline justify-between gap-2">
            <h2 className="animate-fade-up text-sm font-bold uppercase tracking-[0.18em] text-muted-foreground">Gastos rápidos</h2>
            <div className="flex items-center gap-3">
              <span className="text-xs text-muted-foreground">{manage ? "Toca uno para editarlo" : "Toca uno y escribe el monto"}</span>
              <button onClick={() => setManage((m) => !m)}
                className={`flex items-center gap-1.5 rounded-full border px-3 py-1 text-xs font-semibold transition duration-300 ${manage ? "border-primary bg-primary/15 text-primary" : "border-border text-muted-foreground hover:border-primary/40 hover:text-foreground"}`}>
                {manage ? <Check className="h-3.5 w-3.5" /> : <Settings2 className="h-3.5 w-3.5" />}
                {manage ? "Listo" : "Editar"}
              </button>
            </div>
          </div>
          <div className="-mx-4 flex gap-3 overflow-x-auto px-4 pb-2 sm:mx-0 sm:grid sm:grid-cols-3 sm:overflow-visible sm:px-0 md:grid-cols-5">
            {presets.map((p, i) => {
              const Icon = ICONS[p.icon] ?? Home;
              const c = catById(p.cat);
              return (
                <div key={p.id} className="relative min-w-[110px] animate-fade-up" style={{ animationDelay: `${i * 45}ms` }}>
                  <button onClick={() => { if (manage) { setPresetEdit({ ...p }); } else { setPreset(p); setPresetAmount(""); setPresetWho("yo"); } }}
                    className="group flex w-full flex-col items-start gap-2 rounded-2xl border border-border bg-card p-4 text-left backdrop-blur-md transition-all duration-300 hover:-translate-y-1 hover:border-primary/50 hover:shadow-xl hover:shadow-primary/10">
                    <span className="grid h-10 w-10 place-items-center rounded-xl transition-transform duration-300 group-hover:scale-110" style={{ background: `color-mix(in oklab, ${c.color} 15%, transparent)`, color: c.color }}>
                      <Icon className="h-5 w-5" />
                    </span>
                    <span className="text-sm font-semibold">{p.name}</span>
                    <span className="flex items-center gap-1 text-xs font-medium text-muted-foreground transition-colors duration-300 group-hover:text-primary">
                      {manage ? (
                        <>
                          <Settings2 className="h-3 w-3" />
                          editar
                        </>
                      ) : (
                        <>
                          <span className="grid h-4 w-4 place-items-center rounded-full border border-dashed border-current text-[10px] leading-none">+</span>
                          monto
                        </>
                      )}
                    </span>
                  </button>
                  {manage && (
                    <button onClick={() => removePreset(p.id)} aria-label={`Quitar ${p.name}`}
                      className="absolute -right-1.5 -top-1.5 grid h-6 w-6 place-items-center rounded-full border border-border bg-popover text-muted-foreground shadow-md transition duration-300 hover:scale-110 hover:border-destructive/50 hover:text-destructive">
                      <X className="h-3 w-3" />
                    </button>
                  )}
                </div>
              );
            })}
            {manage && (
              <button onClick={() => setPresetEdit({ name: "", cat: "hogar", icon: "sparkles" })}
                className="group flex min-w-[110px] animate-fade-up flex-col items-start gap-2 rounded-2xl border border-dashed border-primary/40 bg-primary/5 p-4 text-left backdrop-blur-md transition-all duration-300 hover:-translate-y-1 hover:border-primary hover:bg-primary/10">
                <span className="grid h-10 w-10 place-items-center rounded-xl bg-primary/15 text-primary transition-transform duration-300 group-hover:scale-110">
                  <Plus className="h-5 w-5" />
                </span>
                <span className="text-sm font-semibold text-primary">Nuevo</span>
                <span className="text-xs text-muted-foreground">agregar gasto</span>
              </button>
            )}
          </div>
        </section>

        <div className="mt-8 grid gap-6 lg:grid-cols-5">
          {/* Categorías */}
          <section className="relative overflow-hidden rounded-3xl border border-border bg-card p-5 backdrop-blur-md lg:col-span-2">
            <div className="animate-blob-alt pointer-events-none absolute -right-16 -top-16 h-40 w-40 rounded-full bg-primary/10 blur-3xl" />
            <h2 className="mb-4 text-sm font-bold uppercase tracking-[0.18em] text-muted-foreground">Por categoría</h2>
            {byCat.length === 0 ? (
              <div className="flex flex-col items-center gap-3 py-10 text-center">
                <div className="grid h-16 w-16 place-items-center rounded-full border-2 border-dashed border-border text-muted-foreground">
                  <Home className="h-6 w-6" />
                </div>
                <p className="max-w-[200px] text-sm text-muted-foreground">Aún no hay gastos. <span className="text-primary/80">Toca un gasto rápido para empezar.</span></p>
              </div>
            ) : (
              <ul className="space-y-3">
                {byCat.map((c, i) => (
                  <li key={c.id} className="animate-fade-up" style={{ animationDelay: `${i * 70}ms` }}>
                    <button onClick={() => setFilter(filter === c.id ? null : c.id)} className={`w-full rounded-xl p-2 text-left transition ${filter === c.id ? "bg-secondary/70" : "hover:bg-secondary/50"}`}>
                      <div className="flex items-center justify-between text-sm">
                        <span className="flex items-center gap-2"><c.icon className="h-4 w-4" style={{ color: c.color }} />{c.name}</span>
                        <span className="font-semibold">{formatMoney(c.total, currency)}</span>
                      </div>
                      <div className="mt-2 h-2 overflow-hidden rounded-full bg-muted">
                        <div className="bar-fill h-full rounded-full" style={{ width: `${(c.total / total) * 100}%`, background: c.color, animationDelay: `${i * 90}ms` }} />
                      </div>
                    </button>
                  </li>
                ))}
              </ul>
            )}
          </section>

          {/* Movimientos */}
          <section className="relative overflow-hidden rounded-3xl border border-border bg-card p-5 backdrop-blur-md lg:col-span-3">
            <div className="animate-blob pointer-events-none absolute -bottom-16 -left-16 h-40 w-40 rounded-full bg-primary-glow/10 blur-3xl" />
            <div className="mb-4 flex items-center justify-between">
              <h2 className="text-sm font-bold uppercase tracking-[0.18em] text-muted-foreground">Movimientos</h2>
              {filter && <button onClick={() => setFilter(null)} className="flex items-center gap-1 rounded-full bg-secondary/70 px-3 py-1 text-xs text-muted-foreground transition hover:text-foreground"><X className="h-3 w-3" />{catById(filter).name}</button>}
            </div>
            {visible.length === 0 ? (
              <div className="flex flex-col items-center gap-3 py-10 text-center">
                <div className="grid h-16 w-16 place-items-center rounded-full border-2 border-dashed border-border text-muted-foreground">
                  <QrCode className="h-6 w-6" />
                </div>
                <p className="text-sm text-muted-foreground">Nada por aquí todavía.</p>
              </div>
            ) : (
              <ul>
                {visible.map((e, i) => {
                  const c = catById(e.cat);
                  return (
                    <li key={e.id} className="group flex animate-fade-up items-center gap-3 rounded-xl px-2 py-3 transition-colors hover:bg-secondary/50" style={{ animationDelay: `${i * 50}ms` }}>
                      <span className="grid h-10 w-10 shrink-0 place-items-center rounded-xl transition-transform duration-300 group-hover:scale-110" style={{ background: `color-mix(in oklab, ${c.color} 15%, transparent)`, color: c.color }}>
                        <c.icon className="h-4 w-4" />
                      </span>
                      <div className="min-w-0 flex-1">
                        <p className="truncate text-sm font-semibold">{e.name}</p>
                        <p className="text-xs text-muted-foreground">
                          {c.name} · {new Date(e.date).toLocaleDateString("es", { day: "numeric", month: "short" })}
                          {e.shared && ` · pagó ${e.who === "yo" ? "tú" : "tu pareja"}`}
                        </p>
                      </div>
                      <span className="text-sm font-bold">{formatMoney(e.amount, currency)}</span>
                      <button onClick={() => setExpenses((p) => p.filter((x) => x.id !== e.id))} className="text-muted-foreground opacity-60 transition hover:text-destructive group-hover:opacity-100" aria-label="Eliminar">
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </li>
                  );
                })}
              </ul>
            )}
          </section>
        </div>
      </div>

      <button onClick={() => setAddOpen(true)} className="group fixed bottom-6 right-6 z-40 flex items-center gap-2 rounded-2xl bg-primary px-6 py-4 font-bold text-primary-foreground shadow-[0_10px_40px_-8px_var(--primary)] transition-all duration-300 hover:scale-105 active:scale-95">
        <Plus className="h-5 w-5 transition-transform duration-300 group-hover:rotate-90" /> Agregar gasto
      </button>

      {addOpen && (
        <Modal onClose={() => setAddOpen(false)} title="Nuevo gasto">
          <div className="space-y-4">
            <input autoFocus placeholder="¿En qué gastaste?" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}
              className="w-full rounded-xl border border-input bg-secondary/40 px-4 py-3 outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/30" />
            <input type="number" inputMode="decimal" placeholder="0.00" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })}
              className="w-full rounded-xl border border-input bg-secondary/40 px-4 py-3 text-2xl font-bold outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/30" />
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
              {CATS.map((c) => (
                <button key={c.id} onClick={() => setForm({ ...form, cat: c.id })}
                  className={`flex items-center gap-2 rounded-xl border p-2 text-xs transition-all duration-200 ${form.cat === c.id ? "border-primary bg-primary/15 shadow-[0_0_16px_-6px_var(--primary)]" : "border-border hover:border-primary/40"}`}>
                  <c.icon className="h-4 w-4" style={{ color: c.color }} />{c.name}
                </button>
              ))}
            </div>
            {mode === "pareja" && (
              <div className="flex rounded-full bg-secondary/60 p-1 text-sm">
                {(["yo", "pareja"] as const).map((w) => (
                  <button key={w} onClick={() => setForm({ ...form, who: w })} className={`flex-1 rounded-full py-2 font-medium transition ${form.who === w ? "bg-primary text-primary-foreground shadow-md shadow-primary/30" : "text-muted-foreground"}`}>
                    Pagué {w === "yo" ? "yo" : "mi pareja"}
                  </button>
                ))}
              </div>
            )}
            <button onClick={submit} className="w-full rounded-xl bg-primary py-3 font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-[1.02]">Guardar</button>
          </div>
        </Modal>
      )}

      {preset && (
        <Modal onClose={() => setPreset(null)} title={`Agregar ${preset.name}`}>
          <div className="space-y-4">
            <div className="flex items-center gap-3 rounded-2xl border border-border bg-secondary/40 p-3">
              <span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl" style={{ background: `color-mix(in oklab, ${catById(preset.cat).color} 15%, transparent)`, color: catById(preset.cat).color }}>
                <PresetGlyph icon={preset.icon} className="h-5 w-5" />
              </span>
              <div className="min-w-0">
                <p className="text-sm font-semibold">{preset.name}</p>
                <p className="text-xs text-muted-foreground">{catById(preset.cat).name}</p>
              </div>
            </div>

            <div>
              <span className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Monto</span>
              <div className="flex items-center gap-2 rounded-xl border border-input bg-secondary/40 px-4 transition focus-within:border-primary focus-within:ring-2 focus-within:ring-primary/30">
                <span className="text-2xl font-bold text-muted-foreground">$</span>
                <input autoFocus type="number" inputMode="decimal" min="0" step="0.01" placeholder="0.00" value={presetAmount}
                  onChange={(e) => setPresetAmount(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && submitPreset()}
                  className="w-full bg-transparent py-3 text-2xl font-bold outline-none placeholder:text-muted-foreground/50" />
              </div>
            </div>

            {mode === "pareja" && (
              <div className="flex rounded-full bg-secondary/60 p-1 text-sm">
                {(["yo", "pareja"] as const).map((w) => (
                  <button key={w} onClick={() => setPresetWho(w)} className={`flex-1 rounded-full py-2 font-medium transition ${presetWho === w ? "bg-primary text-primary-foreground shadow-md shadow-primary/30" : "text-muted-foreground"}`}>
                    Pagué {w === "yo" ? "yo" : "mi pareja"}
                  </button>
                ))}
              </div>
            )}

            <button onClick={submitPreset} disabled={!parseFloat(presetAmount)}
              className="w-full rounded-xl bg-primary py-3 font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-[1.02] disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100">
              Guardar gasto
            </button>
          </div>
        </Modal>
      )}

      {presetEdit && (
        <Modal onClose={() => setPresetEdit(null)} title={presetEdit.id ? "Editar gasto rápido" : "Nuevo gasto rápido"}>
          <div className="space-y-4">
            <div>
              <span className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Nombre</span>
              <input autoFocus placeholder="Netflix, Luz, Gimnasio…" value={presetEdit.name}
                onChange={(e) => setPresetEdit({ ...presetEdit, name: e.target.value })}
                className="w-full rounded-xl border border-input bg-secondary/40 px-4 py-3 outline-none transition placeholder:text-muted-foreground/50 focus:border-primary focus:ring-2 focus:ring-primary/30" />
            </div>

            <div>
              <span className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Categoría</span>
              <div className="flex flex-wrap gap-2">
                {CATS.map((c) => (
                  <button key={c.id} onClick={() => setPresetEdit({ ...presetEdit, cat: c.id })}
                    className={`flex items-center gap-2 rounded-full border px-3 py-2 text-xs font-medium transition duration-300 ${presetEdit.cat === c.id ? "border-primary bg-primary/10 text-foreground" : "border-border text-muted-foreground hover:border-primary/40"}`}>
                    <c.icon className="h-4 w-4 shrink-0" style={{ color: c.color }} />
                    {c.name}
                  </button>
                ))}
              </div>
            </div>

            <div>
              <span className="mb-1.5 block text-xs font-semibold uppercase tracking-[0.18em] text-muted-foreground">Icono</span>
              <div className="flex flex-wrap gap-2">
                {ICON_KEYS.map((k) => (
                  <button key={k} onClick={() => setPresetEdit({ ...presetEdit, icon: k })} aria-label={`Icono ${k}`}
                    className={`grid h-9 w-9 place-items-center rounded-xl border transition duration-300 ${presetEdit.icon === k ? "border-primary bg-primary/15 text-primary" : "border-border text-muted-foreground hover:border-primary/40 hover:text-foreground"}`}>
                    <PresetGlyph icon={k} className="h-4 w-4" />
                  </button>
                ))}
              </div>
            </div>

            <div className="flex gap-2">
              {presetEdit.id && (
                <button onClick={() => { if (presetEdit.id) removePreset(presetEdit.id); setPresetEdit(null); }}
                  className="rounded-xl border border-destructive/40 px-4 py-3 text-sm font-semibold text-destructive transition duration-300 hover:bg-destructive/10">
                  Quitar
                </button>
              )}
              <button onClick={savePreset} disabled={!presetEdit.name.trim()}
                className="flex-1 rounded-xl bg-primary py-3 font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-[1.02] disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100">
                Guardar
              </button>
            </div>
          </div>
        </Modal>
      )}

      {qrOpen && (
        <Modal onClose={() => setQrOpen(false)} title="Emparejar con tu pareja">
          <div className="flex flex-col items-center gap-4 text-center">
            <p className="text-sm text-muted-foreground">Pídele a tu pareja que escanee este código con su celular.</p>
            <div className="animate-icon-in rounded-2xl bg-primary-foreground p-4 shadow-[0_0_30px_-8px_var(--primary-glow)]"><QRCodeSVG value={link} size={200} /></div>
            <p className="text-sm">Tu código: <span className="font-mono font-semibold tracking-widest text-primary">{code}</span></p>
            <div className="flex w-full gap-2">
              <input placeholder="Código de tu pareja" value={joinCode} onChange={(e) => setJoinCode(e.target.value.toUpperCase())}
                className="flex-1 rounded-xl border border-input bg-secondary/40 px-3 py-2 font-mono outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/30" />
              <button onClick={() => { if (joinCode) { localStorage.setItem("gastos-partner", joinCode); setPartner(joinCode); setQrOpen(false); } }}
                className="rounded-xl bg-primary px-4 text-sm font-semibold text-primary-foreground shadow-lg shadow-primary/30 transition hover:scale-105">Unir</button>
            </div>
          </div>
        </Modal>
      )}
    </div>
  );
}

function PresetGlyph({ icon, className }: { icon: string; className?: string }) {
  const Icon = ICONS[icon] ?? Home;
  return <Icon className={className} />;
}

function Modal({ children, title, onClose }: { children: React.ReactNode; title: string; onClose: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-foreground/40 backdrop-blur-sm sm:items-center" onClick={onClose}>
      <div className="w-full max-w-md animate-fade-up rounded-t-3xl border border-border bg-popover p-6 shadow-2xl shadow-primary/10 backdrop-blur-xl sm:rounded-3xl" onClick={(e) => e.stopPropagation()}>
        <div className="mb-4 flex items-center justify-between">
          <h3 className="text-lg font-bold">{title}</h3>
          <button onClick={onClose} aria-label="Cerrar" className="rounded-full p-1 transition hover:bg-secondary"><X className="h-5 w-5 text-muted-foreground" /></button>
        </div>
        {children}
      </div>
    </div>
  );
}